[
  {
    "sys_fairness_reciprocity": "I owe them the same watchfulness they give the rest of us."
  },
  {
    "sys_fairness_reciprocity": "I can't hope for that from others and then refuse it myself."
  },
  {
    "ce_mental_state_attribution": "crews trusted the people up top to do their part",
    "sys_fairness_reciprocity": "I owe those men what they'd owe me"
  },
  {
    "sys_fairness_reciprocity": "They deserve the same regard I'd give my own brother"
  },
  {
    "sys_fairness_reciprocity": "Same standard for me as for them."
  },
  {
    "sys_fairness_reciprocity": "landing on people who had no part in it."
  },
  {
    "sys_fairness_reciprocity": "wrong to keep a debt like that when the chance to pay it is sitting"
  },
  {
    "sys_fairness_reciprocity": "each of us would want the same done for us."
  },
  {
    "sys_fairness_reciprocity": "owed exactly the same basic decency I'd want offered to me"
  },
  {
    "sys_fairness_reciprocity": "People doing their jobs should be able to count on the rest of us"
  }
]
